WITH FilteredInventory AS (SELECT * FROM inventory WHERE YEAR(last_restock) >= 2023 AND last_restock < '2024-10-01'), summary AS (SELECT DATE_FORMAT(last_restock, 'yyyy-MM') AS last_restock_month, ROUND(STDDEV(quantity), 2) AS stddev_quantity FROM FilteredInventory GROUP BY DATE_FORMAT(last_restock, 'yyyy-MM')) SELECT last_restock_month, stddev_quantity FROM summary WHERE stddev_quantity >= 50 ORDER BY last_restock_month DESC
